def olah_siswa(nama, nilai):
    if not isinstance(nama, str) or not nama.strip():
        raise ValueError("Nama wajib diisi")
    if not isinstance(nilai, list) or not nilai:
        raise ValueError("Daftar nilai tidak boleh kosong")
    total = 0
    for angka in nilai:
        if type(angka) is not int or not 0 <= angka <= 100:
            raise ValueError("Nilai harus bilangan bulat 0 sampai 100")
        total += angka
    rata_rata = total / len(nilai)
    status = "Lulus" if rata_rata >= 75 else "Belum lulus"
    return {"nama": nama.strip(), "rata_rata": rata_rata, "status": status}


def main():
    data = [
        {"nama": "Ana", "nilai": [80, 75, 85]},
        {"nama": "Budi", "nilai": [60, 70, 65]},
        {"nama": "Citra", "nilai": [75, 75, 75]},
    ]
    jumlah_lulus = 0
    for siswa in data:
        try:
            hasil = olah_siswa(siswa["nama"], siswa["nilai"])
        except ValueError as error:
            print("Data ditolak:", error)
            continue
        print(f"{hasil['nama']}: {hasil['rata_rata']:.1f} - {hasil['status']}")
        if hasil["status"] == "Lulus":
            jumlah_lulus += 1
    print("Jumlah lulus:", jumlah_lulus)


if __name__ == "__main__":
    main()

import json
from pathlib import Path

LOKASI = Path(__file__).with_name("pengeluaran-latihan.json")


def validasi_data(data):
    if not isinstance(data, list):
        raise ValueError("Isi file harus berupa list")
    for item in data:
        if not isinstance(item, dict):
            raise ValueError("Setiap transaksi harus berupa dictionary")
        if set(item) != {"keterangan", "jumlah"}:
            raise ValueError("Kolom transaksi tidak sesuai")
        if not isinstance(item["keterangan"], str) or not item["keterangan"].strip():
            raise ValueError("Keterangan wajib diisi")
        if type(item["jumlah"]) is not int or item["jumlah"] <= 0:
            raise ValueError("Jumlah harus rupiah bulat positif")
    return data


def muat(lokasi):
    try:
        with lokasi.open(encoding="utf-8") as file:
            data = json.load(file)
    except FileNotFoundError:
        return []
    return validasi_data(data)


def simpan(lokasi, data):
    validasi_data(data)
    sementara = lokasi.with_suffix(".tmp")
    with sementara.open("w", encoding="utf-8") as file:
        json.dump(data, file, ensure_ascii=False, indent=2)
    sementara.replace(lokasi)


def tambah(data, keterangan, jumlah):
    calon = data + [{"keterangan": keterangan.strip(), "jumlah": jumlah}]
    return validasi_data(calon)


def ringkasan(data):
    if not data:
        print("Belum ada transaksi")
        return
    total = 0
    for item in data:
        print(item["keterangan"], "-", item["jumlah"])
        total += item["jumlah"]
    print("Total pengeluaran:", total)


def main():
    try:
        data = muat(LOKASI)
    except (OSError, UnicodeError, ValueError) as error:
        print("File tidak dapat dibaca:", error)
        print("Program berhenti. File lama tidak ditimpa.")
        return
    while True:
        pilihan = input("1=Tambah, 2=Ringkasan, 0=Keluar: ").strip()
        if pilihan == "0":
            print("Selesai")
            break
        if pilihan == "2":
            ringkasan(data)
        elif pilihan == "1":
            keterangan = input("Keterangan: ")
            try:
                jumlah = int(input("Jumlah rupiah: "))
                calon = tambah(data, keterangan, jumlah)
            except ValueError as error:
                print("Input ditolak:", error)
                continue
            try:
                simpan(LOKASI, calon)
            except OSError as error:
                print("Belum tersimpan:", error)
                continue
            data = calon
            print("Transaksi tersimpan")
        else:
            print("Pilihan tidak dikenal")


if __name__ == "__main__":
    main()

def rata_rata(nilai: list[int]) -> float:
    if not isinstance(nilai, list) or not nilai:
        raise ValueError("Nilai harus list yang tidak kosong")
    if any(type(n) is not int or not 0 <= n <= 100 for n in nilai):
        raise ValueError("Setiap nilai harus integer 0..100")
    return sum(nilai) / len(nilai)

def cari_nama(kode: str, data: dict[str, str]) -> str | None:
    return data.get(kode)

